import json

def merge_json():
    with open('people/a.json', 'r') as f:
        a = json.load(f)
    with open('people/b.json', 'r') as f:
        b = json.load(f)

    merged = {}
    for item in a:
        merged[item['id']] = item

    for item in b:
        if item['id'] in merged:
            merged[item['id']].update(item)
        else:
            merged[item['id']] = item

    # The task says: "each item having id, name and email"
    # Let's make sure we only keep those keys.
    final_list = []
    for id, data in merged.items():
        final_list.append({
            "id": data["id"],
            "name": data.get("name"),
            "email": data.get("email")
        })

    # Sort by id ascending
    final_list.sort(key=lambda x: x['id'])

    with open('people/merged.json', 'w') as f:
        json.dump(final_list, f, indent=2)

if __name__ == "__main__":
    merge_json()

